#!/usr/bin/env python3
# O8 S2 (2026-09-08; NARRATIVE_GAPS.md section 6c) — register FROM EDEN TO HAGAR's effects from the verses' own words: the `he`
# built from the pointed DB text (cantillation stripped) by the RUN's own index into the verse, QUOTED; every count claim in
# `ink` VERIFIED against the Tanakh's consonants before the append (S1's lesson: every measured claim through the CLAIMS list).
# Appends to World/step9/effect_vocabulary.yaml as TEXT under `effects:` (a MAPPING); idempotent. The eight REUSED effects
# get their `ink` line extended.
import sqlite3, yaml, re, sys
ROOT = "<repo-old>"
db = sqlite3.connect('file:%s/elijah_docket/tanakh.sqlite?mode=ro' % ROOT, uri=True)
BARE, POINT, TAN = {}, {}, {}
for bk, ch, vs, he in db.execute("SELECT v.book, v.chapter, v.verse, w.he FROM words w JOIN verses v ON w.verse_id=v.id ORDER BY v.book, v.chapter, v.verse, w.idx"):
    TAN.setdefault((bk, ch, vs), []).append(re.sub(r'[\u0591-\u05C7/]', '', he))
    if bk == 'Gen':
        BARE.setdefault((ch, vs), []).append(re.sub(r'[\u0591-\u05C7/]', '', he))
        POINT.setdefault((ch, vs), []).append(''.join(c for c in he if c != '/' and not (0x0591 <= ord(c) <= 0x05AF)))
def seats(tok): return sorted(k for k, ws in BARE.items() if tok in ws)
def run_seats(run):
    ws = run.split(); return sorted(k for k, vv in BARE.items() if any(vv[i:i+len(ws)] == ws for i in range(len(vv) - len(ws) + 1)))
def ttok(tok): return sorted(k for k, ws in TAN.items() if tok in ws)
def trun(run):
    ws = run.split(); return sorted(k for k, vv in TAN.items() if any(vv[i:i+len(ws)] == ws for i in range(len(vv) - len(ws) + 1)))
def H(ch, vs, run, en):
    """the pointed words of the RUN at its verse (the run located in the consonants — a run not found stops the append)"""
    ws, want = BARE[(ch, vs)], run.split()
    idx = [i for i in range(len(ws) - len(want) + 1) if ws[i:i + len(want)] == want]
    assert idx, ('RUN NOT IN VERSE', ch, vs, run)
    return '%s (%s — Gen %d:%d)' % (' '.join(POINT[(ch, vs)][idx[0]:idx[0] + len(want)]), en, ch, vs)
